# ==============================================================================
# 2. CONVERSÃO E QUANTIZAÇÃO Q15
# ==============================================================================
# Se você passou apenas o array float, quantizamos para Q15:
if len(fir_coeffs_q15) == 0 and len(fir_coeffs_f32) > 0:
    fir_coeffs_q15 = np.round(fir_coeffs_f32 * 32767.0).astype(np.int16)

# Normaliza o array Q15 de volta para escala unitária para plotagem comparativa
fir_coeffs_q15_reconstructed = fir_coeffs_q15.astype(np.float64) / 32768.0
print(fir_coeffs_q15_reconstructed)

# ==============================================================================
# 3. CÁLCULO DA RESPOSTA EM FREQUÊNCIA (FFT / FREQZ)
# ==============================================================================
w_f32, h_f32 = signal.freqz(fir_coeffs_f32, worN=8192, fs=FS)
w_q15, h_q15 = signal.freqz(fir_coeffs_q15_reconstructed, worN=8192, fs=FS)

mag_f32_db = 20 * np.log10(np.maximum(np.abs(h_f32), 1e-7))
mag_q15_db = 20 * np.log10(np.maximum(np.abs(h_q15), 1e-7))

# Erro espectral introduzido pela quantização
erro_espectral_db = mag_q15_db - mag_f32_db

# ==============================================================================
# 4. PLOTAGEM DOS GRÁFICOS
# ==============================================================================
plt.figure(figsize=(12, 8))

# Subplot 1: Resposta em Magnitude (Float vs Q15)
plt.subplot(2, 1, 1)
plt.plot(w_f32, mag_f32_db, 'b-', label='Float32 (Original)', linewidth=1.5)
plt.plot(w_q15, mag_q15_db, 'r--', label='Ponto Fixo Q15 (Quantizado)', linewidth=1.2, alpha=0.85)
plt.title(f'Resposta em Frequência do Filtro FIR ({len(fir_coeffs_q15)} Taps) - Fs = {FS} Hz')
plt.xlabel('Frequência (Hz)')
plt.ylabel('Magnitude (dB)')
plt.grid(True, which='both', linestyle='--', alpha=0.6)
plt.ylim([-120, 10])
plt.legend(loc='upper right')

# Subplot 2: Diferença / Degradação Espectral
plt.subplot(2, 1, 2)
plt.plot(w_q15, erro_espectral_db, 'g-', label='Erro de Quantização (Q15 - Float)', linewidth=1.2)
plt.title('Degradação Espectral Residual por Quantização Q15')
plt.xlabel('Frequência (Hz)')
plt.ylabel('Diferença de Magnitude (dB)')
plt.grid(True, which='both', linestyle='--', alpha=0.6)
plt.legend(loc='upper right')

plt.tight_layout()
plt.show()

# ==============================================================================
# 5. DIAGNÓSTICO NUMÉRICO VIA TERMINAL
# ==============================================================================
zeros_count = np.sum(fir_coeffs_q15 == 0)
print(f"Total de Taps: {len(fir_coeffs_q15)}")
print(f"Taps zerados na conversão Q15 (abaixo de 1/32768): {zeros_count} ({(zeros_count/len(fir_coeffs_q15))*100:.1f}%)")
print(f"Soma dos coeficientes Float32: {np.sum(fir_coeffs_f32):.6f}")
print(f"Soma dos coeficientes Q15 (escala 1.0): {np.sum(fir_coeffs_q15_reconstructed):.6f}")